        ["feedbackCopied"] = ["النص طويل؛ نُسخت التفاصيل. الصقها في صفحة GitHub قبل الإرسال.", "The details are long and were copied. Paste them on GitHub before submitting.", "Le texte est long et a été copié. Collez-le sur GitHub avant l’envoi.", "El texto es largo y se copió. Pégalo en GitHub antes de enviarlo."],
        ["feedbackReview"] = ["راجع التفاصيل في GitHub ثم اضغط إرسال هناك.", "Review the details on GitHub, then submit there.", "Vérifiez les détails sur GitHub, puis envoyez-les.", "Revisa los detalles en GitHub y envíalos allí."],
        ["feedbackFailed"] = ["تعذّر فتح صفحة GitHub:", "Could not open GitHub:", "Impossible d’ouvrir GitHub :", "No se pudo abrir GitHub:"],
        ["feedbackPrivacy"] = ["تفتح بصيرة صفحة بلاغ جديد في GitHub؛ راجع ما كتبت قبل الإرسال. لا تُرسل مفاتيح API أو الصور تلقائيًا.", "Baseera opens a new GitHub issue for your review. API keys and images are never attached automatically.", "Baseera ouvre un nouveau ticket GitHub à vérifier. Les clés API et les images ne sont jamais jointes automatiquement.", "Baseera abre una incidencia de GitHub para que la revises. Las claves API y las imágenes nunca se adjuntan automáticamente."],
        ["settings"] = ["الإعدادات", "Settings", "Paramètres", "Configuración"],
        ["welcome"] = ["مساحتك. على طريقتك.", "Your workspace. Your way.", "Votre espace. À votre façon.", "Tu espacio. A tu manera."],
        ["intro"] = ["خمس أدوات، وتجربة واحدة هادئة. اختر ما تحتاجه فقط.", "Five tools, one quiet workspace. Choose only what you need.", "Cinq outils, un espace serein. Choisissez ce qui vous convient.", "Cinco herramientas, un espacio tranquilo. Elige lo que necesitas."],
        ["setup"] = ["لنبدأ بما يناسبك", "Make yourself at home", "Installez-vous", "Hazlo tuyo"],
        ["setupDesc"] = ["فعّل أدواتك المفضلة. يمكنك تغيير كل اختيار لاحقًا.", "Enable your tools. Every choice can be changed later.", "Activez vos outils. Vous pourrez tout modifier ensuite.", "Activa tus herramientas. Puedes cambiarlo después."],
        ["scanDesc"] = ["يفحص محتويات ZIP والسكربتات وبنية الملفات التنفيذية محليًا، ويعرض أدلة الاشتباه وحدود الفحص.", "Inspect ZIP contents, scripts and executable structure locally, with evidence and coverage limits.", "Analyse locale des ZIP, scripts et exécutables, avec indices et limites de couverture.", "Analiza ZIP, scripts y ejecutables localmente, con indicios y límites de cobertura."],
        ["translateDesc"] = ["ترجم النص الظاهر في نافذة مختارة فوق مواضعه. تُرسل لقطة النافذة إلى الخدمة المختارة عند الطلب.", "Translate visible text over a selected window. Its screenshot goes to the chosen service on request.", "Traduisez le texte d’une fenêtre au-dessus de celle-ci. La capture est envoyée au service choisi sur demande.", "Traduce el texto visible sobre la ventana elegida. La captura se envía al servicio elegido cuando lo solicitas."],
        ["updatesDesc"] = ["حدّث تطبيقات WinGet التي تختارها، أو افحص صفحة إصدارات GitHub المحددة يدويًا.", "Update selected WinGet apps, or inspect a manually selected GitHub releases page.", "Mettez à jour les applications WinGet choisies, ou consultez une page de versions GitHub.", "Actualiza aplicaciones WinGet seleccionadas o consulta una página de versiones de GitHub."],
        ["convertDesc"] = ["حوّل PNG وJPEG وBMP وTIFF، أو اجمع الصور في PDF مع الاحتفاظ بالأصول.", "Convert PNG, JPEG, BMP and TIFF, or combine images into a PDF while keeping originals.", "Convertissez PNG, JPEG, BMP et TIFF, ou réunissez les images dans un PDF sans modifier les originaux.", "Convierte PNG, JPEG, BMP y TIFF, o combina imágenes en PDF conservando los originales."],
